using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SuperpositionedEffect", menuName = "Data/Battle/Effects/Enemy/Superpositioned Effect")]
public class SuperpositionedEffect : Effect
{
	[Header("Battle Action List")]
	[SerializeField]
	private BattleActionsList battleActionsList;

	public Dice ConvertCorruptPurifyIntoConfuseAction(Dice dice)
	{
		for (int i = 0; i < dice.GetDiceFaces().Length; i++)
		{
			BattleAction battleAction = dice.GetDiceFaces()[i].BattleAction;
			if (battleAction is CorruptAction || battleAction is PurifyAction)
			{
				battleAction = GetConvertedBattleAction(battleAction);
			}
			dice.GetDiceFaces()[i].BattleAction = battleAction;
			dice.GetDiceFaces()[i].ActionValue = dice.GetDiceFaces()[i].ModifiedActionValue;
			dice.GetDiceFaces()[i].ActionValueModifier = 0;
			if (dice.GetDiceFaces()[i].EnableSecondAction)
			{
				BattleAction battleAction2 = dice.GetDiceFaces()[i].SecondBattleAction;
				if (battleAction2 is CorruptAction || battleAction2 is PurifyAction)
				{
					battleAction2 = GetConvertedBattleAction(battleAction2);
				}
				dice.GetDiceFaces()[i].SecondBattleAction = battleAction2;
				dice.GetDiceFaces()[i].SecondActionValue = dice.GetDiceFaces()[i].SecondModifiedActionValue;
				dice.GetDiceFaces()[i].SecondActionValueModifier = 0;
			}
		}
		return dice;
	}

	private BattleAction GetConvertedBattleAction(BattleAction battleAction)
	{
		string text = "";
		if (!battleAction.name.Contains("CorruptionSource"))
		{
			text = ((!battleAction.name.Contains("Corrupt")) ? battleAction.name.Replace("Purify", "Confuse") : battleAction.name.Replace("Corrupt", "Confuse"));
		}
		else
		{
			text = battleAction.name.Replace("CorruptionSource", "");
			text = ((!battleAction.name.Contains("Corrupt")) ? text.Replace("Purify", "Confuse") : text.Replace("Corrupt", "Confuse"));
			text = "CorruptionSource" + text;
		}
		return battleActionsList.GetBattleAction(text);
	}
}
